const tracks=[{title:'A Good Conversation',file:'public/assets/music/a-good-conversation.ogg',mood:'Warm keys, slow afternoon'},{title:'The Scenic Route',file:'public/assets/music/the-scenic-route.ogg',mood:'A little curiosity, in sound'}];const audio=new Audio();audio.preload='metadata';let trackIndex=0;{const volume=Number(saved('volume',.25));audio.volume=Number.isFinite(volume)?Math.max(0,Math.min(1,volume)):.25;}let musicWindow=null,autoplayPending=true,musicUserPaused=false;
function syncMusic(){const playing=!audio.paused&&!audio.ended;$('.music-mini').classList.toggle('is-playing',playing);$('#music-mini-title').textContent=audio.src?tracks[trackIndex].title:'A little soundtrack for your visit';$('#music-mini-state').textContent=playing?'ON REPEAT · '+(audio.volume===0?'MUTED':'PLAYING'):autoplayPending&&!musicUserPaused?'CLICK ANYWHERE FOR SOUND':'SOUNDTRACK · PAUSED';$('.music-mini').setAttribute('aria-label',`Open music player, ${playing?'playing':'sound off'}`);const toggle=$('#music-quick-toggle');toggle.setAttribute('aria-pressed',String(playing));toggle.setAttribute('aria-label',playing?'Pause background music':'Play background music');toggle.textContent=playing?'||':'▶';if(musicWindow?.el.isConnected){const body=musicWindow.body;$('#track-title',body).textContent=tracks[trackIndex].title;$('#track-mood',body).textContent=tracks[trackIndex].mood;$('#music-play',body).textContent=playing?'||':'▶';$('#music-play',body).setAttribute('aria-label',playing?'Pause music':'Play music');$('#music-status',body).textContent=playing?'Playing · the soundtrack keeps looping.':autoplayPending&&!musicUserPaused?'Your browser is waiting for a click before it allows sound.':'Paused. Press Play whenever you like.';const duration=Number.isFinite(audio.duration)?audio.duration:0;$('#music-seek',body).max=String(duration||1);$('#music-seek',body).value=String(audio.currentTime||0);$('#music-time',body).textContent=`${Math.floor(audio.currentTime||0)}s / ${Math.floor(duration)}s`;}}
async function playMusic({automatic=false}={}){if(automatic&&musicUserPaused)return false;if(!automatic)musicUserPaused=false;autoplayPending=false;if(!audio.src)audio.src=tracks[trackIndex].file;try{await audio.play();syncMusic();return true}catch(error){if(automatic&&error.name==='NotAllowedError'&&!musicUserPaused){autoplayPending=true;syncMusic();return false}if(musicUserPaused){syncMusic();return false}syncMusic();if(musicWindow?.el.isConnected)$('#music-status',musicWindow.body).textContent='Playback could not start. Try Play again, or continue with sound off.';if(!automatic)toast('Music could not start. You can keep exploring with sound off.');return false}}
function pauseMusic(){musicUserPaused=true;autoplayPending=false;audio.pause();syncMusic()}
