for(const event of ['play','pause','timeupdate','loadedmetadata'])audio.addEventListener(event,syncMusic);audio.addEventListener('ended',()=>{switchTrack(1,!musicUserPaused)});audio.addEventListener('error',()=>{autoplayPending=false;syncMusic();if(musicWindow?.el.isConnected)$('#music-status',musicWindow.body).textContent='Audio unavailable. You can keep exploring without sound.'});
$('#music-quick-toggle').onclick=()=>audio.paused?playMusic():pauseMusic();
const tryGestureMusic=e=>{if(!autoplayPending||musicUserPaused||!e.isTrusted||e.target.closest('.music-controls,.music-range,#music-quick-toggle'))return;if(e.type==='keydown'&&['Shift','Control','Alt','Meta','Escape'].includes(e.key))return;playMusic({automatic:true})};document.addEventListener('click',tryGestureMusic);document.addEventListener('keydown',tryGestureMusic);
function renderMusic(w){musicWindow=w;w.body.innerHTML=head('THE LITTLE SOUNDTRACK','A little company for the rabbit holes.','Two original instrumental sketches, looping through your visit. Pause or change the volume whenever you like.')+`<div class="music-cover"><span class="cover-art" aria-hidden="true">✳</span><h4 id="track-title">${tracks[trackIndex].title}</h4><p id="track-mood">${tracks[trackIndex].mood}</p></div><div class="music-controls"><button id="music-prev" aria-label="Previous track">←</button><button id="music-play" aria-label="Play music">▶</button><button id="music-next" aria-label="Next track">→</button></div><div class="music-range"><label for="music-seek">Position</label><input id="music-seek" type="range" min="0" max="1" value="0" step=".1"><output id="music-time">0s / 0s</output></div><div class="music-range"><label for="music-volume">Volume</label><input id="music-volume" type="range" min="0" max="1" step=".01" value="${audio.volume}"><output id="volume-value">${Math.round(audio.volume*100)}%</output></div><p class="disclosure" id="music-status"></p><p class="disclosure">Original soundtrack · CC0. It tries to start on arrival; browsers that block autoplay require your first click. Both tracks repeat until paused. A manual pause lasts for this visit; your volume is saved locally. The pause button stays in the dock area, including on phones.</p>`;$('#music-play',w.body).onclick=()=>audio.paused?playMusic():pauseMusic();$('#music-prev',w.body).onclick=()=>switchTrack(-1,!audio.paused);$('#music-next',w.body).onclick=()=>switchTrack(1,!audio.paused);$('#music-volume',w.body).oninput=e=>{audio.volume=Number(e.target.value);save('volume',audio.volume);$('#volume-value',w.body).textContent=Math.round(audio.volume*100)+'%'};$('#music-seek',w.body).oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)};syncMusic()}
function renderGame(w){const pairs=['People','Ideas','Build','Explore','Listen','Learn'];let deck=[],revealed=[],matched=new Set(),moves=0,busy=false,timer;function setup(){deck=[...pairs,...pairs].map((value,index)=>({value,index}));for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}revealed=[];matched=new Set();moves=0;busy=false;clearTimeout(timer);draw()}function draw(){const focused=document.activeElement?.dataset.card;w.body.innerHTML=head('A TINY ORIGINAL SIDE QUEST','Make a few connections.','Find the six matching pairs. No timers, scores sent anywhere, sounds, or competitive pressure.')+`<div class="game-meta"><span id="game-progress" role="status">${matched.size/2} / 6 pairs · ${moves} turns</span><button class="secondary" id="game-reset">New board</button></div><div class="game-board">${deck.map((card,i)=>`<button class="game-card ${matched.has(i)?'is-matched':revealed.includes(i)?'is-revealed':''}" data-card="${i}" aria-label="${matched.has(i)||revealed.includes(i)?esc(card.value):'Hidden card '+(i+1)}" ${matched.has(i)?'disabled':''}>${matched.has(i)||revealed.includes(i)?esc(card.value):'?'}</button>`).join('')}</div><p class="disclosure">A small, original memory game built for this site. All game state is local to this window.</p>`;$$('[data-card]',w.body).forEach(b=>b.onclick=()=>flip(Number(b.dataset.card)));$('#game-reset',w.body).onclick=setup;if(focused!==undefined){const target=$(`[data-card="${focused}"]`,w.body);if(target&&!target.disabled)target.focus({preventScroll:true});else $('[data-card]:not(:disabled)',w.body)?.focus({preventScroll:true})}}function flip(i){if(busy||matched.has(i)||revealed.includes(i))return;revealed.push(i);if(revealed.length===2){moves++;if(deck[revealed[0]].value===deck[revealed[1]].value){revealed.forEach(x=>matched.add(x));revealed=[];if(matched.size===deck.length){companionReact('celebrating','Connections made. Very on brand.');toast('All connected. Nicely done!')}}else{busy=true;timer=setTimeout(()=>{revealed=[];busy=false;if(w.el.isConnected)draw()},1000)}}draw()}w.cleanup.push(()=>clearTimeout(timer));setup()}

