let bootFinished=false;function finishBoot(){if(bootFinished)return;bootFinished=true;if(!musicUserPaused)playMusic({automatic:true});$('#boot').classList.add('is-done');setTimeout(()=>$('#boot').hidden=true,reduced()?0:350);try{sessionStorage.setItem(STORAGE+'boot-v1','seen')}catch{}$('#desktop').focus({preventScroll:true})}$('#skip-boot').onclick=finishBoot;let seen=false;try{seen=sessionStorage.getItem(STORAGE+'boot-v1')==='seen'}catch{}setTimeout(finishBoot,reduced()||seen?80:1800);
